      "path": "lib/index.js",
      "content": "/**
 * dsh-pdf-reader — DeepSeek Harness plugin bundle for content-aware PDF reading
 * by vision models.
 *
 * Registers three model-facing tools (pdf_scan / pdf_read_page /
 * pdf_render_region) backed by a PyMuPDF helper. Theme: read the content the
 * right way — text pages via extraction, figure/table/math pages via a
 * high-DPI region crop fed to read_image — so a two-column paper's vector
 * figures and tables are never lost to the whole-page ~800x800 token ceiling.
 */
import { registerPdfTools } from './tools.js'

export const name = 'dsh-pdf-reader'

export const inject = ['tools', 'subprocess', 'fs', 'timer']

export function apply(ctx) {
  registerPdfTools(ctx)
}
"
    },
    {
      "path": "lib/tools.js",
      "content": "/**
 * dsh-pdf-reader agent-facing tools: pdf_scan / pdf_read_page / pdf_render_region.
 *
 * Each tool first resolves a Python interpreter with PyMuPDF. When the
 * environment is incomplete it returns a descriptive warning (what's missing,
 * how to fix it) and lets the agent handle it — it never hard-fails.
 *
 * NOTE: tools are built here as plain registry-ready objects rather than via
 * `defineTool` from `@deepseek-ai/dsh-tools`, so the plugin has NO runtime
 * peer import and works out of the box with `dsh plugin add link:<path>`
 * (no `npm install` needed). `ctx.tools.register()` accepts this shape.
 */
import { fileURLToPath } from 'node:url'
import path from 'node:path'
import { resolvePdfPython } from './python.js'
import { runPython } from './runner.js'

const HELPER = fileURLToPath(new URL('./pdf_helper.py', import.meta.url))

export const TOOL_CAPS = Object.freeze({ doneCapMs: 120_000, graceMs: 15_000 })

function sessionCwd(exec) {
  return exec?.agent?.session?.header?.cwd || process.cwd()
}

function absPath(p, cwd) {
  return p && path.isAbsolute(p) ? p : path.resolve(cwd, p)
}

async function runHelper(ctx, exec, argv, limits = TOOL_CAPS) {
  const cwd = sessionCwd(exec)
  const env = await resolvePdfPython(ctx.subprocess, ctx.fs, ctx.timer, cwd, exec?.signal)
  if (!env.ready) return { ok: false, warning: env.warning, missing: env.missing }

  const out = await runPython(
    ctx.subprocess, ctx.timer,
    [env.interpreter, HELPER, ...argv],
    cwd, limits, exec?.signal,
  )
  if (out.timedOut) return { ok: false, error: `PDF helper timed out after ${limits.doneCapMs}ms; the process tree was terminated.` }
  if (out.exitCode !== 0) return { ok: false, error: (out.stderr || 'PDF helper failed').trim() }
  try {
    return JSON.parse(out.stdout)
  } catch {
    return { ok: false, error: 'PDF helper returned malformed JSON: ' + out.stdout.slice(0, 200) }
  }
}

function renderResult(_args, value) {
  if (value && typeof value === 'object') {
    const text = value.error || value.warning
      ? `⚠ ${value.error || value.warning}`
      : JSON.stringify(value, null, 2)
    return [{ type: 'text', text }]
  }
  return [{ type: 'text', text: String(value) }]
}

/** Build a registry-ready tool definition (matches the shape defineTool returns). */
function tool({ name, description, parameters, timeoutMs, execute }) {
  return {
    name,
    description,
    parameters,
    output: { schema: { type: 'object', additionalProperties: true }, render: renderResult },
    timeoutMs,
    execute,
  }
}

function objectParams(properties, required) {
  return { type: 'object', properties, required, additionalProperties: false }
}

export function registerPdfTools(ctx) {
  ctx.tools.register(
    tool({
      name: 'pdf_scan',
      description:
        'Whole-document overview. Scan a PDF and return a per-page content profile so you can ' +
        'plan how to read each page, BEFORE spending a render budget. For every page: textChars, ' +
        'columns, figures (vector regions), rasterImages, tables, formulaRisk, hasGraphics, ' +
        'hasTextLayer. Then per page use pdf_read_page (mode="mixed" for full coverage: preview ' +
        '+ text + auto region crops) and pdf_render_region for targeted zooms. Requires Python ' +
        'with pymupdf.',
      parameters: objectParams({
        pdf_path: { type: 'string', description: 'Absolute or session-relative path of the PDF.' },
        pages: { type: 'string', description: 'Optional comma-separated page list, e.g. "2,5-8". Default: all pages.' },
      }, ['pdf_path']),
      timeoutMs: 120_000,
      async execute(args, exec) {
        const a = args ?? {}
        const cwd = sessionCwd(exec)
        if (!a.pdf_path) return { ok: false, error: 'pdf_path is required' }
        const argv = ['scan', absPath(a.pdf_path, cwd)]
        if (a.pages) argv.push('--pages', String(a.pages))
        return runHelper(ctx, exec, argv)
      },
    }),
  )

  ctx.tools.register(
    tool({
      name: 'pdf_read_page',
      description:
        'Read one page of a PDF. Recommended per-page workflow: ' +
        '(1) PREVIEW — mode="mixed" returns a low-res full-page render (fullPage) plus the ' +
        'extracted text, so you see the whole layout (formulas, table gridlines, figure ' +
        'placement) without burning the token budget; ' +
        '(2) CONTENT — mode="mixed" also auto-detects every figure/table region and renders it ' +
        'as a high-DPI PNG. All PNGs are saved to <cwd>/.dsh-pdf-reader and returned only as ' +
        'PATHS (never inlined), so long/heavy content stays in the cache, not in your context — ' +
        'read them via read_image; ' +
        '(3) REFINE — if a specific area is still too small or was not auto-cropped (an ' +
        'uncropped formula, a crowded table cell, a sub-figure), zoom it with pdf_render_region ' +
        'on the exact [x0,y0,x1,y1] bbox you read off the fullPage preview. ' +
        'For a whole-document overview first run pdf_scan. mode="auto" returns just the largest ' +
        'figure/table image (or the text) per the page profile; mode="text" forces extraction; ' +
        'mode="render" forces a render of an explicit region. Needs Python+pymupdf.',
      parameters: objectParams({
        pdf_path: { type: 'string', description: 'Absolute or session-relative PDF path.' },
        page: { type: 'number', description: '1-based page number to read.' },
        mode: { type: 'string', description: '"auto" (default), "text", "mixed", or "render".', enum: ['auto', 'text', 'mixed', 'render'] },
        dpi: { type: 'number', description: 'Optional DPI override for a render; default fills the budget.' },
        region: { type: 'array', description: '[x0,y0,x1,y1] in points, for mode=render.', items: { type: 'number' } },
      }, ['pdf_path', 'page']),
      timeoutMs: 120_000,
      async execute(args, exec) {
        const a = args ?? {}
        const cwd = sessionCwd(exec)
        if (!a.pdf_path || !a.page) return { ok: false, error: 'pdf_path and page are required' }
        const argv = ['read', absPath(a.pdf_path, cwd), String(a.page), '--out-dir', path.join(cwd, '.dsh-pdf-reader')]
        if (a.mode) argv.push('--mode', a.mode)
        if (a.dpi) argv.push('--dpi', String(a.dpi))
        if (Array.isArray(a.region) && a.region.length === 4) argv.push('--region', ...a.region.map(String))
        return runHelper(ctx, exec, argv)
      },
    }),
  )

  ctx.tools.register(
    tool({
      name: 'pdf_render_region',
      description:
        'Targeted high-res render of one [x0,y0,x1,y1] bbox (in points) on a page — the REFINE ' +
        'step. After the low-res full-page preview and auto region crops, zoom any area that is ' +
        'still too small or ambiguous (an uncropped formula, a crowded table cell, a sub-figure) ' +
        'by rendering the exact bbox at ~800x800 budget DPI. The PNG is saved to ' +
        '<cwd>/.dsh-pdf-reader and returned as a PATH — read it with read_image. ' +
        'Pull the bbox from pdf_scan or from the fullPage preview. Needs Python+pymupdf.',
      parameters: objectParams({
        pdf_path: { type: 'string', description: 'Absolute or session-relative PDF path.' },
        page: { type: 'number', description: '1-based page number.' },
        region: { type: 'array', description: '[x0,y0,x1,y1] in points.', items: { type: 'number' } },
        dpi: { type: 'number', description: 'Optional DPI override; default fills the budget.' },
      }, ['pdf_path', 'page', 'region']),
      timeoutMs: 120_000,
      async execute(args, exec) {
        const a = args ?? {}
        const cwd = sessionCwd(exec)
        if (!a.pdf_path || !a.page || !Array.isArray(a.region) || a.region.length !== 4) {
          return { ok: false, error: 'pdf_path, page, and region [x0,y0,x1,y1] are required' }
        }
        const argv = ['render', absPath(a.pdf_path, cwd), String(a.page), ...a.region.map(String), '--out-dir', path.join(cwd, '.dsh-pdf-reader')]
        if (a.dpi) argv.push('--dpi', String(a.dpi))
        return runHelper(ctx, exec, argv)
      },
    }),
  )
}
"
    },
    {
      "path": "lib/runner.js",
      "content": "/**
 * Spawn a Python helper invocation and collect its stdio.
 *
 * Hardening (mirrors dsh-graphlint's runner):
 *  - force UTF-8 via PYTHONIOENCODING so a localized code page cannot garble
 *    the JSON payload;
 *  - wire the caller's AbortSignal so a cooperative timeout terminates the tree;
 *  - cap the exit wait so a wedged process cannot hang the tool turn;
 *  - never shell-interpret argv (plain argv array).
 */

export const DEFAULT_LIMITS = Object.freeze({ doneCapMs: 120_000, graceMs: 15_000 })

export function runPython(subprocess, timer, argv, cwd, limits = DEFAULT_LIMITS, signal) {
  // Merge partial limits with the defaults: callers may pass only `doneCapMs`
  // (e.g. the import probe in python.js). `subprocess.spawn` validates that
  // `graceMs` is a positive finite number, so an omitted field (undefined)
  // would be rejected — fill it from the defaults instead of forwarding it.
  const l = { ...DEFAULT_LIMITS, ...(limits || {}) }
  const handle = subprocess.spawn({
    argv,
    cwd,
    stdio: {
      stdin: 'ignore',
      stdout: { maxBytes: 8 * 1024 * 1024 },
      stderr: { maxBytes: 512 * 1024 },
    },
    graceMs: l.graceMs,
    signal,
    env: { PYTHONIOENCODING: 'utf-8', PYTHONDONTWRITEBYTECODE: '1' },
  })
  const done = new Promise((resolve) => {
    const timeout = timer.timeout(() => {
      handle.terminate()
      resolve({ exitCode: null, stdout: '', stderr: '', timedOut: true })
    }, l.doneCapMs)
    handle.done.then(
      (outcome) => {
        timeout()
        resolve({
          exitCode: outcome.exitCode,
          stdout: handle.collected?.stdout?.readFrom(0).text ?? '',
          stderr: handle.collected?.stderr?.readFrom(0).text ?? '',
          timedOut: false,
        })
      },
      () => {
        timeout()
        resolve({ exitCode: null, stdout: '', stderr: '', timedOut: false })
      },
    )
  })
  return done
}
"
    },
    {
      "path": "lib/python.js",
      "content": "/**
 * Python + PyMuPDF resolution for dsh-pdf-reader.
 *
 * Resolution is ordered and module-aware, matching the user's intent:
 *   1. try the "main" Python on PATH (the one the harness/agent is running
 *      against) — if it can `import pymupdf`, use it;
 *   2. otherwise try python3 / py, then the project-local venvs (.venv/venv/env)
 *      under the session cwd — first one that can `import pymupdf` wins;
 *   3. if none can, return a structured `warning` naming exactly what is
 *      missing and the command that would fix it, and let the agent decide.
 *
 * (Unlike a CLI tool such as graphlint, we must resolve a *Python interpreter*
 *  AND verify the *module* imports — pymupdf is a library, not an executable.)
 */
import { join } from 'node:path'
import { runPython } from './runner.js'

const VENV_BASES = ['.venv', 'venv', 'env']
const WINDOWS = { bin: 'Scripts', exe: 'python.exe' }
const POSIX = { bin: 'bin', exe: 'python' }

/** Ordered, de-duplicated candidate interpreter paths. */
export async function listInterpreters(subprocess, fs, cwd) {
  const seen = new Set()
  const out = []
  const push = (p) => {
    if (p && !seen.has(p)) {
      seen.add(p)
      out.push(p)
    }
  }
  const rels = process.platform === 'win32' ? WINDOWS : POSIX

  // 1) the explicitly activated venv (highest priority) — the user is using
  //    this Python right now; if it has pymupdf it is the intended target.
  if (process.env.VIRTUAL_ENV) {
    push(join(process.env.VIRTUAL_ENV, rels.bin, rels.exe))
  }

  // 2) main Python on PATH (activator / harness runtime)
  for (const cmd of ['python', 'python3', 'py']) {
    try {
      const exe = await subprocess.resolveExecutable(cmd)
      push(exe)
    } catch {
      /* PATH lookup failed */
    }
  }

  // 3) project-local virtualenv interpreters under the session cwd
  for (const base of VENV_BASES) {
    push(join(cwd, base, rels.bin, rels.exe))
  }
  return out
}

/**
 * Run `interpreter -c <probe>` and return {ok, version} for an import probe.
 */
export async function probeImport(subprocess, timer, interpreter, module, signal) {
  const out = await runPython(
    subprocess, timer,
    [`${interpreter}`, '-c', `import ${module}, sys; print(getattr(${module}, '__version__', '?'))`],
    process.cwd(),
    { doneCapMs: 20_000 },
    signal,
  )
  if (out.exitCode === 0) return { ok: true, version: out.stdout.trim() }
  return { ok: false, stderr: out.stderr.trim() }
}

function buildWarning(candidates) {
  const w = ['PDF reading is not available — no Python interpreter with `pymupdf` was found.']
  if (candidates.length) w.push(`Tried: ${candidates.join(', ')}.`)
  else w.push('No Python interpreter was found on PATH or in this project.')
  w.push('To enable, either:')
  w.push('  - install pymupdf into your main Python:  python -m pip install pymupdf')
  w.push('  - or create a project venv:  python -m venv .venv && .venv\\Scripts\\python.exe -m pip install pymupdf')
  w.push('Re-run this tool once a Python with pymupdf is available.')
  return w.join('\n')
}

/** Resolve a ready interpreter+pymupdf, or a clear actionable warning. */
export async function resolvePdfPython(subprocess, fs, timer, cwd, signal) {
  const candidates = await listInterpreters(subprocess, fs, cwd)
  for (const interpreter of candidates) {
    const pym = await probeImport(subprocess, timer, interpreter, 'pymupdf', signal)
    if (pym.ok) {
      const four = await probeImport(subprocess, timer, interpreter, 'pymupdf4llm', signal)
      return { ready: true, interpreter, pymupdf: true, pymupdf4llm: four.ok }
    }
  }
  // figure out which was missing (python vs pymupdf) for a clearer message
  return {
    ready: false,
    warning: buildWarning(candidates),
    missing: ['a Python interpreter with the `pymupdf` package'],
    interpreter: candidates[0] ?? null,
  }
}
