    {
      "path": "lib/pdf_helper.py",
      "content": "# -*- coding: utf-8 -*-
"""dsh-pdf-reader engine (PyMuPDF).

Agent-facing subcommands (JSON to stdout):
  scan   <pdf>                              -> per-page content profile
  read   <pdf> <page> [mode|auto] [dpi] [region...] -> text OR rendered region path
  render <pdf> <page> <x0 y0 x1 y1> [dpi]   -> rendered crop path

Design notes:
  * "content completeness first": candidate figure/table/math regions are
    rendered to fill the model's ~640k-pixel budget (DeepSeek ~800x800 /
    384-token), so nothing legible is lost inside the budget; the crop is
    token-optimal because it is rendered AT the budget, not beyond it.
  * Figures are located by clustering vector drawing ops (get_drawings) plus
    raster placement rects (get_image_rects). Tables are ALSO drawn with
    vector rules, so a table region shows up as a drawing cluster too; this
    avoids find_tables' well-known false positives on plot grids.
  * Math is detected via math/symbol font names (cmmi/cmsy/Type3/STIX/...)
    plus a LaTeX producer (pdfTeX/LaTeX), since the extracted text layer
    garbles formulas.
"""
import argparse
import contextlib
import io
import json
import math
import os
import sys

PT2IN = 1.0 / 72.0
# DeepSeek per-image budget (~800x800-equivalent / 384 tokens); DSH's
# DEFAULT_REQUEST_IMAGE_PIXEL_BUDGET is also 640000.
PIXEL_BUDGET = 640_000
MATH_FONT_RE = ("cmmi", "cmsy", "cmmib", "cmex", "msam", "msbm", "type3",
                "stix", "mtpro", "xits", "euler", "fourier", "txapp", "math")


def _cluster_rects(rects, gap=8.0, min_area=400.0):
    """Union nearby rects into clusters (vector figure/table regions)."""
    import pymupdf as m
    rects = [m.Rect(r) for r in rects]
    changed = True
    while changed:
        changed = False
        out = []
        while rects:
            cur = rects.pop()
            merged = False
            for idx, existing in enumerate(out):
                grow = m.Rect(cur)
                grow.x0 -= gap; grow.y0 -= gap; grow.x1 += gap; grow.y1 += gap
                if grow.intersects(existing):
                    merged_rect = m.Rect(existing)
                    merged_rect.include_rect(cur)
                    out[idx] = merged_rect
                    merged = True; changed = True
                    break
            if not merged:
                out.append(cur)
        rects = out
    return [r for r in rects if not r.is_empty and r.get_area() > min_area]


def _columns(page):
    """Best-effort column count from text block left edges (2-col detection)."""
    try:
        blocks = page.get_text("blocks")
    except Exception:
        return 1
    xs = sorted(round(b[0]) for b in blocks if len(b) >= 5 and b[6] == 0)
    if not xs:
        return 1
    xs = sorted(set(xs))
    gaps = [(xs[i + 1] - xs[i], xs[i], xs[i + 1]) for i in range(len(xs) - 1)]
    if not gaps:
        return 1
    big = max(gaps) if gaps else (0, 0, 0)
    # a big horizontal gap in block-left edges => separate columns
    return 2 if big[0] > 0.20 * page.rect.width else 1


def _math_fonts(page):
    names = []
    try:
        for f in page.get_fonts():
            name = ((f[3] or "") + " " + (f[4] or "")).strip()
            if name:
                names.append(name)
    except Exception:
        pass
    low = " ".join(names).lower()
    hit = sorted({n for n in names if any(k in n.lower() for k in MATH_FONT_RE)})
    return {"fonts": names, "mathFonts": hit, "producer_latex": None}


def _text_stats(page):
    text = ""
    try:
        text = page.get_text("text")
    except Exception:
        pass
    chars = len(text)
    # replacement + PUA counts are a weak proxy; math/symbol fonts are the
    # authoritative signal, so we report both but route on fonts + figures.
    pua = sum(1 for c in text if 0xE000 <= ord(c) <= 0xF8FF or ord(c) == 0xFFFD)
    return {"textChars": chars, "mojibakeCount": pua,
            "hasTextLayer": chars > 0}


def scan_page(doc, page_num):
    page = doc[page_num - 1]
    pr = page.rect
    page_area = pr.get_area() or 1.0
    # "meaningful graphics" = a cluster covering >=1% of the page; this skips
    # small logos, CC badges, and decorative rules that would otherwise trigger
    # a pointless render of a mostly-text page.
    mini = 0.01 * page_area
    img_rects = []
    try:
        for img in page.get_images(full=True):
            xref = img[0]
            for r in page.get_image_rects(xref):
                if r.get_area() >= mini:
                    img_rects.append(list(r))
    except Exception:
        pass
    draw_clusters = []
    try:
        draws = page.get_drawings()
        # include THIN connector lines/arrows too: they belong to their figure.
        # filter on the LARGER dimension, not the area: a connector arrow is a
        # zero-width or zero-height line whose rect area is ~0, but it is the
        # very element that bridges a figure's components. Dropping it (as an
        # area filter would) splits one flowchart into a big cluster plus a tiny
        # orphan that falls below min_area and is lost — clipping the bbox.
        # cluster first (proximity merges lines into their figure), then keep
        # only clusters >=1% of the page (drops logos/decorative rules).
        all_items = [d["rect"] for d in draws
                     if max(d["rect"].width, d["rect"].height) > 2.0]
        draw_clusters = [list(r) for r in _cluster_rects(all_items, gap=10.0, min_area=mini)]
    except Exception:
        pass

    tables = []
    try:
        for t in page.find_tables().tables:
            tables.append({"bbox": list(t.bbox), "rows": t.row_count,
                           "cols": t.col_count})
    except Exception:
        pass

    fs = _math_fonts(page)
    ts = _text_stats(page)
    producer = (doc.metadata or {}).get("producer", "") or ""
    latex = ("pdftex" in producer.lower() or "latex" in producer.lower()
             or bool(fs["mathFonts"]))

    return {
        "page": page_num,
        "size": [round(pr.width, 1), round(pr.height, 1)],
        "columns": _columns(page),
        "figures": draw_clusters,
        "rasterImages": img_rects,
        "tables": tables,
        "math": {"fonts": fs["fonts"], "mathFonts": fs["mathFonts"],
                 "likelyLatex": latex},
        # this page has a visual element text extraction cannot convey
        "hasGraphics": bool(draw_clusters or img_rects or tables),
        # text extraction may still garble stacked formulas; flag it so the
        # agent can choose to render a specific equation region if exact
        # structure is needed (pymupdf extracts inline math well, though).
        "formulaRisk": latex and bool(fs["mathFonts"]),
        "text": ts,
    }


def area_dpi(w_pt, h_pt, budget=PIXEL_BUDGET):
    return 72.0 * (budget / max(1.0, w_pt * h_pt)) ** 0.5


def _largest(rects):
    if not rects:
        return None
    import pymupdf as m
    return max((m.Rect(r) for r in rects), key=lambda r: r.get_area())


def best_region(profile):
    """Pick the crop that preserves the most content: largest raster or the
    largest vector cluster (covers figures AND tables). Returns (bbox, label)."""
    cands = []
    for r in profile.get("figures", []):
        cands.append((r, "figure"))
    for r in profile.get("rasterImages", []):
        cands.append((r, "raster"))
    for t in profile.get("tables", []):
        cands.append((t["bbox"], "table"))
    if not cands:
        return None, None
    import pymupdf as m
    cands = [(m.Rect(c), label) for c, label in cands]
    return max(cands, key=lambda c: c[0].get_area())


def cmd_scan(args):
    import pymupdf as m
    doc = m.open(args.pdf)
    wanted = _page_selector(args.pages, doc.page_count)
    out = {
        "ok": True,
        "pdf": args.pdf,
        "producer": (doc.metadata or {}).get("producer", ""),
        "pages": doc.page_count,
        "pageSize": [round(doc[0].rect.width, 1), round(doc[0].rect.height, 1)],
        "pages_profile": [scan_page(doc, i) for i in wanted],
    }
    doc.close()
    return out


def _page_selector(spec, total):
    """Parse '2,5-8' into a sorted 1-based page list."""
    pages = []
    if not spec:
        return list(range(1, total + 1))
    for part in str(spec).split(","):
        part = part.strip()
        if not part:
            continue
        if "-" in part:
            lo, hi = part.split("-", 1)
            pages.extend(range(int(lo), int(hi) + 1))
        else:
            pages.append(int(part))
    return [p for p in pages if 1 <= p <= total]


def cmd_render(args):
    import pymupdf as m
    doc = m.open(args.pdf)
    page = doc[args.page - 1]
    rect = m.Rect(args.region)
    if rect.is_empty or rect.get_area() <= 0:
        rect = page.rect
    dpi = args.dpi or round(area_dpi(rect.width, rect.height))
    pm = page.get_pixmap(clip=rect, matrix=m.Matrix(dpi / 72.0, dpi / 72.0))
    os.makedirs(args.out_dir, exist_ok=True)
    path = os.path.join(args.out_dir,
                        f"{os.path.basename(args.pdf)}-p{args.page}-{int(rect.x0)}x{int(rect.y0)}.png")
    pm.save(path)
    doc.close()
    return {"ok": True, "path": path, "bbox": list(rect), "dpi": dpi,
            "width": pm.width, "height": pm.height,
            "pixels": pm.width * pm.height, "budget": PIXEL_BUDGET,
            "scaled": (pm.width * pm.height > PIXEL_BUDGET)}


def _render_region_image(page, rect, out_dir, pdf_base, page_num, dpi_override=None):
    """Render one rect at the area-budget dpi and save a PNG; return its dict."""
    import pymupdf as m
    if rect.is_empty or rect.get_area() <= 0:
        rect = page.rect
    dpi = dpi_override or round(area_dpi(rect.width, rect.height))
    pm = page.get_pixmap(clip=rect, matrix=m.Matrix(dpi / 72.0, dpi / 72.0))
    os.makedirs(out_dir, exist_ok=True)
    path = os.path.join(out_dir,
                        f"{pdf_base}-p{page_num}-{int(rect.x0)}x{int(rect.y0)}.png")
    pm.save(path)
    return {"bbox": list(rect), "path": path, "dpi": dpi, "width": pm.width,
            "height": pm.height, "pixels": pm.width * pm.height,
            "budget": PIXEL_BUDGET, "scaled": (pm.width * pm.height > PIXEL_BUDGET)}


def _dedupe_regions(cands, overlap_ratio=0.5):
    """Keep the largest of overlapping regions. find_tables can re-report a
    figure (plot grid) as a 'table', so drop near-duplicate candidates."""
    import pymupdf as m
    ordered = sorted(((m.Rect(r), label) for r, label in cands),
                     key=lambda c: c[0].get_area(), reverse=True)
    kept = []
    for rect, label in ordered:
        dup = False
        for krect, _ in kept:
            inter = rect & krect
            if (not inter.is_empty
                    and inter.get_area() >= overlap_ratio * min(rect.get_area(), krect.get_area())):
                dup = True
                break
        if not dup:
            kept.append((rect, label))
    return kept


def _table_from_blocks(page, min_sci=3, gap=14.0, max_line=72, max_iter=20):
    """Detect table regions from text-block structure.

    A results table's cell text is dense with scientific notation (e.g.
    '3.00E+02 (5.0E-05)' or '3.00e+02 ± 5.00e-05'), which is a strong, low
    false-positive signal that find_tables frequently misses (it prefers the
    plot grids). Seed on blocks with >= min_sci such tokens, then absorb
    adjacent *short-line* blocks (column headers / cell rows) so the region is
    not clipped. Returns deduped (Rect, 'table') pairs.
    """
    import re
    import pymupdf as m
    blocks = [b for b in page.get_text("blocks") if len(b) >= 5]

    def sci(txt):
        return len(re.findall(r"[0-9.]+[Ee][-+]?[0-9]+|[0-9.]+\s*[×x*]\s*10",
                              txt or ""))

    def longest(txt):
        return max((len(l.strip()) for l in (txt or "").split("\n")), default=0)

    seeds = [b for b in blocks if sci(b[4]) >= min_sci]
    regions = []
    for seed in seeds:
        x0, y0, x1, y1 = seed[0], seed[1], seed[2], seed[3]
        for _ in range(max_iter):
            grew = False
            for b in blocks:
                bx0, by0, bx1, by1, txt = b[0], b[1], b[2], b[3], b[4]
                if not txt.strip():
                    continue
                if bx0 >= x0 and by0 >= y0 and bx1 <= x1 and by1 <= y1:
                    continue  # already inside the region
                if longest(txt) > max_line:
                    continue  # a prose line, not a table cell
                vgap = max(0, max(y0 - by1, by0 - y1))
                if vgap > gap:
                    continue
                ox = min(x1, bx1) - max(x0, bx0)
                if ox < 0.5 * min(x1 - x0, bx1 - bx0):
                    continue
                nx0, ny0, nx1, ny1 = min(x0, bx0), min(y0, by0), max(x1, bx1), max(y1, by1)
                if (nx0, ny0, nx1, ny1) != (x0, y0, x1, y1):
                    x0, y0, x1, y1 = nx0, ny0, nx1, ny1
                    grew = True
            if not grew:
                break
        regions.append((m.Rect(x0, y0, x1, y1), "table"))
    return _dedupe_regions(regions)


def cmd_read(args):
    import pymupdf as m
    doc = m.open(args.pdf)
    page_num = args.page
    page = doc[page_num - 1]
    profile = scan_page(doc, page_num)
    mode = args.mode or "auto"
    # route on THIS page's actual graphics (figures/raster/tables) — not on a
    # document-level "is LaTeX" flag, which would render every page.
    has_gfx = bool(profile["hasGraphics"])
    result = {"ok": True, "page": page_num, "mode": mode, "profile": profile}

    # mode=mixed: cover the WHOLE page in one call — the extracted text AND every
    # figure/raster/table region (deduped) as high-DPI PNGs, PLUS a full-page
    # reference render so 2-D layout (display formulas, table gridlines, figure
    # placement) that text extraction flattens is never lost.
    if mode == "mixed":
        text = page.get_text("text").strip()
        md = None
        try:
            import pymupdf4llm
            md = pymupdf4llm.to_markdown(doc.path, pages=[page_num])
        except Exception:
            md = None
        pdf_base = os.path.basename(args.pdf)
        cands = [(r, "figure") for r in profile.get("figures", [])]
        cands += [(r, "raster") for r in profile.get("rasterImages", [])]
        cands += [(t["bbox"], "table") for t in profile.get("tables", [])]
        # results tables whose cell text is dense with scientific notation are a
        # reliable signal that find_tables often misses (it mis-reports the plot
        # grids instead). Add the block and its neighboring header/cell rows.
        cands += [(list(r), "table") for r, _lbl in _table_from_blocks(page)]
        regions = _dedupe_regions(cands)
        images = []
        for rect, label in regions:
            img = _render_region_image(page, rect, args.out_dir, pdf_base, page_num)
            img["label"] = label
            images.append(img)
        result["kind"] = "mixed"
        result["text"] = text
        result["textChars"] = len(text)
        result["formulaRisk"] = profile["formulaRisk"]
        if md:
            result["markdown"] = md
        result["regions"] = images
        result["fullPage"] = _render_region_image(
            page, page.rect, args.out_dir, pdf_base, page_num)
        doc.close()
        return result

    if mode == "text" or (mode == "auto" and not has_gfx):
        text = page.get_text("text").strip()
        md = None
        try:
            import pymupdf4llm
            md = pymupdf4llm.to_markdown(doc.path, pages=[page_num])
        except Exception:
            md = None
        result["kind"] = "text"
        result["text"] = text
        result["textChars"] = len(text)
        result["formulaRisk"] = profile["formulaRisk"]
        if md:
            result["markdown"] = md
        doc.close()
        return result

    # render the region (explicit or best) at area-budget dpi
    import pymupdf as m
    if args.region:
        rect = m.Rect(args.region)
        reason = "explicit-region"
    else:
        (bbox, label) = best_region(profile)
        if bbox is None:
            bbox = page.rect
            label = "full-page"
        rect = bbox
        reason = f"auto-{label}"
    dpi = args.dpi or round(area_dpi(rect.width, rect.height))
    pm = page.get_pixmap(clip=rect, matrix=m.Matrix(dpi / 72.0, dpi / 72.0))
    os.makedirs(args.out_dir, exist_ok=True)
    path = os.path.join(args.out_dir,
                        f"{os.path.basename(args.pdf)}-p{page_num}-{int(rect.x0)}x{int(rect.y0)}.png")
    pm.save(path)
    doc.close()
    result["kind"] = "image"
    result["region"] = list(rect)
    result["reason"] = reason
    result["path"] = path
    result["dpi"] = dpi
    result["width"] = pm.width
    result["height"] = pm.height
    result["pixels"] = pm.width * pm.height
    result["budget"] = PIXEL_BUDGET
    return result


def main():
    p = argparse.ArgumentParser(prog="pdf_helper")
    sub = p.add_subparsers(dest="cmd", required=True)

    s = sub.add_parser("scan"); s.add_argument("pdf")
    s.add_argument("--pages", default=None,
                   help="comma-separated page list/range, e.g. '2,5-8' (default: all)")
    s.set_defaults(fn=cmd_scan)
    r = sub.add_parser("render")
    r.add_argument("pdf"); r.add_argument("page", type=int)
    r.add_argument("region", nargs=4, type=float)
    r.add_argument("--dpi", type=float, default=None)
    r.add_argument("--out-dir", default=None)
    r.set_defaults(fn=cmd_render)
    rd = sub.add_parser("read")
    rd.add_argument("pdf"); rd.add_argument("page", type=int)
    rd.add_argument("--mode", default="auto")
    rd.add_argument("--dpi", type=float, default=None)
    rd.add_argument("--region", nargs=4, type=float, default=None)
    rd.add_argument("--out-dir", default=None)
    rd.set_defaults(fn=cmd_read)

    args = p.parse_args()
    if not getattr(args, "out_dir", None):
        args.out_dir = os.path.join(os.environ.get("TEMP", os.getcwd()), "dsh-pdf-reader")
    # The stdout contract is exactly one JSON line. PyMuPDF's find_tables() (and
    # similar layout routines) print advisory chatter (e.g. "Consider using the
    # pymupdf_layout package ...") on some builds/versions, which would corrupt
    # the JSON for the caller. Mute BOTH Python-level prints (redirect_stdout)
    # and C-level writes (fd 1 -> /dev/null) while the command runs, then emit
    # ONLY the JSON result to the real stdout.
    saved_stdout_fd = os.dup(1)
    real_stdout = sys.stdout
    devnull_fd = os.open(os.devnull, os.O_WRONLY)
    os.dup2(devnull_fd, 1)
    os.close(devnull_fd)
    failed = False
    try:
        with contextlib.redirect_stdout(io.StringIO()):
            try:
                out = args.fn(args)
            except Exception as e:  # noqa: BLE001
                out = {"ok": False, "error": str(e)}
                failed = True
    finally:
        os.dup2(saved_stdout_fd, 1)
        os.close(saved_stdout_fd)
    real_stdout.write(json.dumps(out, ensure_ascii=False) + "\n")
    real_stdout.flush()
    if failed:
        sys.exit(1)


